{# ===== DYNAMIC DATA: CHANGE doc.employee / doc.year to your real field names ===== #}
{% set w2_emp = doc.employee %}
{# Year: first 4 digits of year / tax_year / fiscal_year. If none is found it is 0 and ALL submitted stubs of the employee are used #}
{% set w2_year = ((doc.year or doc.tax_year or doc.fiscal_year or '') | string)[:4] | int %}

{# Check which Salary Component fields exist, so the print never errors if a field is missing #}
{% set sc_cols = frappe.db.sql("""
    SELECT COLUMN_NAME AS col
    FROM information_schema.COLUMNS
    WHERE TABLE_SCHEMA = DATABASE()
      AND TABLE_NAME = 'tabSalary Component'
      AND COLUMN_NAME IN ('custom_include_in_retirement_plan', 'custom_w2_box_12_code')
""", as_dict=True) | map(attribute='col') | list %}

{# Box 13: components ticked "Include in Retirement Plan" with an amount this year #}
{% if 'custom_include_in_retirement_plan' in sc_cols %}
{% set retirement_rows = frappe.db.sql("""
    SELECT sd.salary_component, SUM(sd.amount) AS total
    FROM `tabSalary Detail` sd
    INNER JOIN `tabSalary Slip` ss ON ss.name = sd.parent
    INNER JOIN `tabSalary Component` sc ON sc.name = sd.salary_component
    WHERE ss.employee = %(emp)s
      AND ss.docstatus = 1
      AND (%(year)s = 0 OR YEAR(ss.posting_date) = %(year)s)
      AND sd.parentfield = 'deductions'
      AND sc.custom_include_in_retirement_plan = 1
    GROUP BY sd.salary_component
    HAVING SUM(sd.amount) > 0
""", {"emp": w2_emp, "year": w2_year}, as_dict=True) %}
{% else %}
{% set retirement_rows = [] %}
{% endif %}

{# Box 14: same checkbox (Include in Retirement Plan), name and yearly total #}
{% if 'custom_include_in_retirement_plan' in sc_cols %}
{% set box14_rows = frappe.db.sql("""
    SELECT sd.salary_component, SUM(sd.amount) AS total
    FROM `tabSalary Detail` sd
    INNER JOIN `tabSalary Slip` ss ON ss.name = sd.parent
    INNER JOIN `tabSalary Component` sc ON sc.name = sd.salary_component
    WHERE ss.employee = %(emp)s
      AND ss.docstatus = 1
      AND (%(year)s = 0 OR YEAR(ss.posting_date) = %(year)s)
      AND sd.parentfield = 'deductions'
      AND sc.custom_include_in_retirement_plan = 1
    GROUP BY sd.salary_component
    HAVING SUM(sd.amount) > 0
    ORDER BY sd.salary_component
""", {"emp": w2_emp, "year": w2_year}, as_dict=True) %}
{% else %}
{% set box14_rows = [] %}
{% endif %}

{# Box 12: one row per "W-2 Box 12 Code" (DD, D, E, G ...), amounts added together #}
{% if 'custom_w2_box_12_code' in sc_cols %}
{% set box12_rows = frappe.db.sql("""
    SELECT sc.custom_w2_box_12_code AS code, SUM(sd.amount) AS total
    FROM `tabSalary Detail` sd
    INNER JOIN `tabSalary Slip` ss ON ss.name = sd.parent
    INNER JOIN `tabSalary Component` sc ON sc.name = sd.salary_component
    WHERE ss.employee = %(emp)s
      AND ss.docstatus = 1
      AND (%(year)s = 0 OR YEAR(ss.posting_date) = %(year)s)
      AND IFNULL(sc.custom_w2_box_12_code, '') != ''
    GROUP BY sc.custom_w2_box_12_code
    HAVING SUM(sd.amount) > 0
    ORDER BY sc.custom_w2_box_12_code
""", {"emp": w2_emp, "year": w2_year}, as_dict=True) %}
{% else %}
{% set box12_rows = [] %}
{% endif %}

{% set b12a = box12_rows[0] if box12_rows|length > 0 else None %}
{% set b12b = box12_rows[1] if box12_rows|length > 1 else None %}
{% set b12c = box12_rows[2] if box12_rows|length > 2 else None %}
{% set b12d = box12_rows[3] if box12_rows|length > 3 else None %}

<style>
    @page {
        size: A4;
        margin: 0;
    }

    body {
        margin: 0;
        padding: 0;
        font-family: "Courier New", Courier, monospace;
    }

    .w2-canvas {
        position: relative;
        width: 7in;
        height: 10in;
        margin: 0 auto;
        background: url("") no-repeat;
        background-size: 7in 10.9in;
    }

    /* Common value style */
    .w2-val {
        position: absolute;
        font-size: 9px;
        font-weight: 700;
        white-space: nowrap;
    }

    .w2-left {
        text-align: left;
    }

    .w2-center {
        text-align: center;
    }

    .w2-right {
        text-align: right;
    }

    .checkbox {
        font-size: 10px;
        font-weight: 700;
    }
</style>

<div class="w2-canvas">

    {# --- Global Company Fetch --- #}
    {% set comp_doc = frappe.get_all("Company", fields=["name","company_name"], limit=1)[0] %}
    {% set comp_name = comp_doc.company_name or "" %}
    {% set comp_id = comp_doc.name or "" %}

    {# --- Company Address (checkbox checked) --- #}
    {% set comp_addr = frappe.db.sql("""
    SELECT address_line1, address_line2, city, state, pincode, country
    FROM `tabAddress`
    WHERE is_your_company_address = 1
    LIMIT 1
    """, as_dict=True) %}
    {% set comp_addr = comp_addr[0] if comp_addr else {} %}

    {# --- Employee Details --- #}
    {% if doc.employee %}
    {% set emp = frappe.db.get_value("Employee", {"name": doc.employee}, [
    "employee_name",
    "custom_address_line_1","custom_address_line_2",
    "custom_city","custom_stateprovince","custom_zip_postal_code","custom_country"
    ], as_dict=True) or {} %}
    {% else %}
    {% set emp = {} %}
    {% endif %}


    <!-- Box a – SSN -->
    <div class="w2-val w2-center" style="top:0.22in; left:1.1in; width:2.8in;">
        {{ doc.social_security_number }}
    </div>

    <!-- Box b – EIN -->
    <div class="w2-val w2-center" style="top:0.56in; left:0.25in; width:3.2in;">
        {{ doc.employer_identification_number_ein }}
    </div>

    <!-- Box 1 -->
    <div class="w2-val w2-right" style="top:0.56in; left:3.59in; width:1.6in;">
        {{ "{:,.2f}".format(doc.wages_tips_other_compensation | float) }}
    </div>

    <!-- Box 2 -->
    <div class="w2-val w2-right" style="top:0.56in; left:5.15in; width:1.6in;">
        {{ "{:,.2f}".format(doc.federal_income_tax_withheld | float) }}
    </div>

    <!-- Box c – Employer address -->
    <div class="w2-val w2-left" style="top:0.86in; left:0.25in; width:3.2in; line-height:1.1;">
        {{ comp_name }}
        {% if comp_id and comp_id != comp_name %} ({{ comp_id }}){% endif %}<br>

        {% if comp_addr.address_line1 %}{{ comp_addr.address_line1 }}<br>{% endif %}
        {% if comp_addr.address_line2 %}{{ comp_addr.address_line2 }}<br>{% endif %}
        {% if comp_addr.city or comp_addr.state or comp_addr.pincode %}
        {{ comp_addr.city or "" }} {{ comp_addr.state or "" }} {{ comp_addr.pincode or "" }}<br>
        {% endif %}
        {% if comp_addr.country %}{{ comp_addr.country }}{% endif %}
    </div>

    <!-- Box 3 -->
    <div class="w2-val w2-right" style="top:0.89in; left:3.55in; width:1.6in;">
        {{ "{:,.2f}".format(doc.social_security_wages | float) }}
    </div>

    <!-- Box 4 -->
    <div class="w2-val w2-right" style="top:0.89in; left:5.15in; width:1.6in;">
        {{ "{:,.2f}".format(doc.social_security_tax_withheld | float) }}
    </div>

    <!-- Box 5 -->
    <div class="w2-val w2-right" style="top:1.23in; left:3.59in; width:1.6in;">
        {{ "{:,.2f}".format(doc.medicare_wages_and_tips | float) }}
    </div>

    <!-- Box 6 -->
    <div class="w2-val w2-right" style="top:1.23in; left:5.15in; width:1.6in;">
        {{ "{:,.2f}".format(doc.medicare_tax_withheld | float) }}
    </div>

    <!-- Box d – Control number -->
    <div class="w2-val w2-left" style="top:1.89in; left:0.25in; width:3.2in;">
        {{ doc.control_number }}
    </div>

    <!-- Box 7 -->
    <div class="w2-val w2-right" style="top:2.32in; left:3.55in; width:1.6in;">
    </div>

    <!-- Box 8 -->
    <div class="w2-val w2-right" style="top:2.32in; left:5.15in; width:1.6in;">
    </div>

    <!-- Box e – Employee name -->
    <div class="w2-val w2-left" style="top:2.16in; left:0.26in; width:3.2in;">
        <span style="display:inline-block; width:1.68in;">
            {{ doc.first_name }} {% if doc.middle_initial %}{{ doc.middle_initial }}{% endif %}
        </span>
        <span style="display:inline-block; width:1.7in;">
            {{ doc.last_name }}
        </span>
    </div>

    <!-- Box f – Employee address -->
    <div class="w2-val w2-left" style="top:2.55in; left:0.25in; width:3.2in; line-height:1.1;">
        {% if emp.custom_address_line_1 %}{{ emp.custom_address_line_1 }}<br>{% endif %}
        {% if emp.custom_address_line_2 %}{{ emp.custom_address_line_2 }}<br>{% endif %}
        {% if emp.custom_city or emp.custom_stateprovince or emp.custom_zip_postal_code %}
        {{ emp.custom_city or "" }} {{ emp.custom_stateprovince or "" }} {{ emp.custom_zip_postal_code or "" }}<br>{{ emp.custom_country or "" }}
        {% endif %}
    </div>

    <!-- Box 9 -->
    <div class="w2-val w2-right" style="top:2.75in; left:3.55in; width:1.6in;">

    </div>

    <!-- Box 10 -->
    <div class="w2-val w2-right" style="top:2.75in; left:5.15in; width:1.6in;">
    </div>

    <!-- Box 11 -->
    <div class="w2-val w2-right" style="top:3.35in; left:3.55in; width:1.6in;">
    </div>

    <!-- Box 12a: code and amount come from "W-2 Box 12 Code" on Salary Component -->
    <div class="w2-val w2-left" style="top:2.16in; left:5.8in; width:1.7in;">
        {% if b12a %}&nbsp;&nbsp; {{ b12a.code }} &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; {{ "{:,.2f}".format(b12a.total | float) }}{% endif %}
    </div>

    <!-- Box 12b -->
    <div class="w2-val w2-left" style="top:3.15in; left:5.2in; width:1.7in;">
        {% if b12b %}&nbsp;&nbsp; {{ b12b.code }} &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; {{ "{:,.2f}".format(b12b.total | float) }}{% endif %}
    </div>

    <!-- Box 12c -->
    <div class="w2-val w2-left" style="top:3.45in; left:5.2in; width:1.7in;">
        {% if b12c %}&nbsp;&nbsp; {{ b12c.code }} &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; {{ "{:,.2f}".format(b12c.total | float) }}{% endif %}
    </div>

    <!-- Box 12d -->
    <div class="w2-val w2-left" style="top:3.75in; left:5.2in; width:1.7in;">
        {% if b12d %}&nbsp;&nbsp; {{ b12d.code }} &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; {{ "{:,.2f}".format(b12d.total | float) }}{% endif %}
    </div>

    <!-- Box 13 checkboxes -->
    <div class="w2-val checkbox" style="top:2.79in; left:4.04in;">{% if doc.statutory_employee %}x{% endif %}</div>
    {# Retirement plan: "x" when a component ticked "Include in Retirement Plan" has an amount #}
    <div class="w2-val checkbox" style="top:2.55in; left:4.82in">{% if retirement_rows %}x{% endif %}</div>
    <div class="w2-val checkbox" style="top:3.62in; left:5.58in;">{% if doc.third_party_sick_pay %}x{% endif %}</div>

    <!-- Box 14: name and amount of each component ticked "Include in Retirement Plan" -->
    {% if box14_rows %} <div class="w2-val w2-left" style="top:2.85in; left:4.12in; width:3.2in;">
        {% for r in box14_rows %}{{ r.salary_component }} &nbsp;{{ "{:,.2f}".format(r.total | float) }}{% if not loop.last %}<br>{% endif %}{% endfor %}
    </div> {% endif %}

    <!-- Boxes 15–20 -->
    <div class="w2-val w2-left" style="top:4.92in; left:0.25in;"></div>
    <div class="w2-val w2-left" style="top:4.92in; left:1.05in;"></div>
    <div class="w2-val w2-right" style="top:4.92in; left:2.35in; width:1.15in;">
    </div>
    <div class="w2-val w2-right" style="top:4.92in; left:3.65in; width:1.15in;">
    </div>
    <div class="w2-val w2-right" style="top:4.92in; left:4.95in; width:1.15in;">
    </div>
    <div class="w2-val w2-right" style="top:4.92in; left:6.25in; width:1.15in;">
    </div>
    <div class="w2-val w2-left" style="top:5.22in; left:4.95in; width:2.5in;">
    </div>
</div>
